 FOR r IN SELECT * FROM jsonb_to_recordset($data_v51$[{"course":"typescript","ordinal":1,"title":"Literal Types","theory":"Literal Types beschränken einen Wert auf genau bestimmte Zeichenketten oder Zahlen, nicht nur den allgemeinen Typ string oder number.","example":"type Status=\"open\"|\"closed\";","example_note":"Status erlaubt ausschließlich die beiden genannten Texte.","task":"Deklariere drei mögliche Bestellzustände.","q1":{"question":"Welche Aussage erklärt „Literal Types“ richtig?","options":["Mit typeof oder anderen Prüfungen verengt TypeScript einen Uniontyp innerhalb eines Codeblocks.","Literal Types beschränken einen Wert auf genau bestimmte Zeichenketten oder Zahlen, nicht nur den allgemeinen Typ string oder number.","Generics bewahren den Zusammenhang zwischen Eingabe- und Ausgabetyp, ohne den unsicheren Typ any zu verwenden."],"correct":1,"explanation":"Literal Types beschränken einen Wert auf genau bestimmte Zeichenketten oder Zahlen, nicht nur den allgemeinen Typ string oder number."},"q2":{"question":"Was zeigt das Beispiel zu „Literal Types“?","options":["Innerhalb des if-Zweigs weiß der Typechecker, dass x Text ist.","Der Ausgabetyp entspricht dem Eingabetyp T.","Status erlaubt ausschließlich die beiden genannten Texte."],"correct":2,"explanation":"Status erlaubt ausschließlich die beiden genannten Texte."}},{"course":"typescript","ordinal":2,"title":"Type Narrowing","theory":"Mit typeof oder anderen Prüfungen verengt TypeScript einen Uniontyp innerhalb eines Codeblocks.","example":"function len(x:string|number){if(typeof x===\"string\")return x.length;return x;}","example_note":"Innerhalb des if-Zweigs weiß der Typechecker, dass x Text ist.","task":"Unterscheide Zahlen und Texte in einer Funktion.","q1":{"question":"Welche Aussage erklärt „Type Narrowing“ richtig?","options":["readonly verbietet nachträgliche Zuweisungen an eine Eigenschaft bei der Typprüfung; es friert Objekte zur Laufzeit nicht tief ein.","keyof erzeugt einen Typ aus den erlaubten Schlüsseln eines Objekttyps.","Mit typeof oder anderen Prüfungen verengt TypeScript einen Uniontyp innerhalb eines Codeblocks."],"correct":2,"explanation":"Mit typeof oder anderen Prüfungen verengt TypeScript einen Uniontyp innerhalb eines Codeblocks."},"q2":{"question":"Was zeigt das Beispiel zu „Type Narrowing“?","options":["Innerhalb des if-Zweigs weiß der Typechecker, dass x Text ist.","Ein späterer Versuch, id zu überschreiben, erzeugt einen TypeScript-Fehler.","Key erlaubt id und name, aber keinen unbekannten Schlüssel."],"correct":0,"explanation":"Innerhalb des if-Zweigs weiß der Typechecker, dass x Text ist."}},{"course":"typescript","ordinal":3,"title":"Readonly","theory":"readonly verbietet nachträgliche Zuweisungen an eine Eigenschaft bei der Typprüfung; es friert Objekte zur Laufzeit nicht tief ein.","example":"interface User{readonly id:number}","example_note":"Ein späterer Versuch, id zu überschreiben, erzeugt einen TypeScript-Fehler.","task":"Markiere einen Datenbankschlüssel als readonly.","q1":{"question":"Welche Aussage erklärt „Readonly“ richtig?","options":["readonly verbietet nachträgliche Zuweisungen an eine Eigenschaft bei der Typprüfung; es friert Objekte zur Laufzeit nicht tief ein.","Generics bewahren den Zusammenhang zwischen Eingabe- und Ausgabetyp, ohne den unsicheren Typ any zu verwenden.","Pick<T,K> bildet aus einem vorhandenen Typ einen kleineren Typ mit ausgewählten Eigenschaften."],"correct":0,"explanation":"readonly verbietet nachträgliche Zuweisungen an eine Eigenschaft bei der Typprüfung; es friert Objekte zur Laufzeit nicht tief ein."},"q2":{"question":"Was zeigt das Beispiel zu „Readonly“?","options":["Der Ausgabetyp entspricht dem Eingabetyp T.","Ein späterer Versuch, id zu überschreiben, erzeugt einen TypeScript-Fehler.","Andere Felder aus User sind im neuen Typ nicht enthalten."],"correct":1,"explanation":"Ein späterer Versuch, id zu überschreiben, erzeugt einen TypeScript-Fehler."}},{"course":"typescript","ordinal":4,